/** Lightweight 3D canvas fallback. Uses the same scene, camera and raycasting.
 * WebGL remains the primary renderer. This path trades reflections and shader
 * effects for compatibility on machines where WebGL 2 is disabled.
 */
import * as T from './vendor/three.module.js';
export class SoftwareRenderer {
  constructor({canvas}){this.domElement=canvas;this.ctx=canvas.getContext('2d');if(!this.ctx)throw new Error('Canvas rendering unavailable');this.capabilities={getMaxAnisotropy:()=>1};this.info={render:{calls:0,triangles:0}};this.pixelRatio=1;this.color='#141019';this.v=new T.Vector3();this.normal=new T.Vector3();this.normalMatrix=new T.Matrix3();this.mvp=new T.Matrix4();this.proj=new T.Matrix4();this.col=new T.Color();this.light=new T.Vector3(.4,.8,.6).normalize();this.on=false;this.lastFrame=0;}
  setClearColor(c){this.color=new T.Color(c).getStyle();}
  setPixelRatio(){this.pixelRatio=1;}
  setSize(w,h){this.width=w;this.height=h;this.domElement.width=w;this.domElement.height=h;}
  setAnimationLoop(callback){this.callback=callback;if(!callback){this.on=false;return;}if(this.on)return;this.on=true;const tick=time=>{if(!this.on)return;requestAnimationFrame(tick);if(time-this.lastFrame<32)return;this.lastFrame=time;this.callback?.(time);};requestAnimationFrame(tick);}
  render(scene,camera){const ctx=this.ctx,w=this.width,h=this.height;ctx.fillStyle=this.color;ctx.fillRect(0,0,w,h);const bg=ctx.createRadialGradient(w*.72,h*.52,0,w*.72,h*.52,w*.53);bg.addColorStop(0,'#372030');bg.addColorStop(1,'#141019');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);scene.updateMatrixWorld();camera.updateMatrixWorld();this.proj.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse);const items=[];let calls=0;
  const visit=obj=>{if(!obj.visible)return;if(obj.isMesh||obj.isLineSegments||obj.isPoints){const geo=obj.geometry,mat=Array.isArray(obj.material)?obj.material[0]:obj.material;if(geo&&mat?.visible!==false&&geo.attributes.position){calls++;this.mvp.multiplyMatrices(this.proj,obj.matrixWorld);const p=geo.attributes.position;const vertices=[];for(let i=0;i<p.count;i++){this.v.fromBufferAttribute(p,i).applyMatrix4(this.mvp);vertices.push([this.v.x*w*.5+w*.5,-this.v.y*h*.5+h*.5,this.v.z]);}if(obj.isPoints){items.push({type:'points',vertices,color:mat.color?.getStyle()||'#fff6e8',alpha:mat.opacity??1,z:0});}else if(obj.isLineSegments){const ix=geo.index;const n=ix?ix.count:p.count;for(let i=0;i<n;i+=2){const a=vertices[ix?ix.getX(i):i],b=vertices[ix?ix.getX(i+1):i+1];if(!a||!b||a[2]<-1||b[2]<-1||a[2]>1||b[2]>1)continue;items.push({type:'line',a,b,z:(a[2]+b[2])/2,color:mat.color?.getStyle()||'#ff79ad',alpha:mat.opacity??1});}}else if(mat.map?.image&&geo.type==='PlaneGeometry'){const corners=[vertices[0],vertices[1],vertices[3],vertices[2]];if(corners.every(v=>v[2]>=-1&&v[2]<=1))items.push({type:'texture',corners,image:mat.map.image,z:corners.reduce((s,v)=>s+v[2],0)/4-.00045,alpha:mat.opacity??1});}else{this.normalMatrix.getNormalMatrix(obj.matrixWorld);const ix=geo.index,n=ix?ix.count:p.count;for(let i=0;i<n;i+=3){const ia=ix?ix.getX(i):i,ib=ix?ix.getX(i+1):i+1,ic=ix?ix.getX(i+2):i+2;const a=vertices[ia],b=vertices[ib],c=vertices[ic];if(!a||!b||!c||a[2]<-1||b[2]<-1||c[2]<-1||a[2]>1||b[2]>1||c[2]>1)continue;if(Math.max(a[0],b[0],c[0])<0||Math.min(a[0],b[0],c[0])>w||Math.max(a[1],b[1],c[1])<0||Math.min(a[1],b[1],c[1])>h)continue;const cross=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);if(mat.side!==T.DoubleSide&&cross>0)continue;let shade=.85;if(geo.attributes.normal){this.normal.fromBufferAttribute(geo.attributes.normal,ia).applyMatrix3(this.normalMatrix).normalize();shade=.48+Math.max(0,this.normal.dot(this.light))*.65;}if(mat.emissiveIntensity>0)shade=1.1;this.col.copy(mat.color||new T.Color(0xffffff)).multiplyScalar(shade);items.push({type:'triangle',a,b,c,z:(a[2]+b[2]+c[2])/3,color:this.col.getStyle(),alpha:mat.opacity??1});}}}}for(const child of obj.children)visit(child);};visit(scene);items.sort((a,b)=>(a.type==='texture')!==(b.type==='texture')?(a.type==='texture'?1:-1):b.z-a.z);let triangles=0;for(const item of items){ctx.globalAlpha=item.alpha;switch(item.type){case'triangle':ctx.fillStyle=item.color;ctx.beginPath();ctx.moveTo(item.a[0],item.a[1]);ctx.lineTo(item.b[0],item.b[1]);ctx.lineTo(item.c[0],item.c[1]);ctx.closePath();ctx.fill();ctx.strokeStyle=item.color;ctx.lineWidth=.4;ctx.stroke();triangles++;break;case'line':ctx.strokeStyle=item.color;ctx.lineWidth=.65;ctx.beginPath();ctx.moveTo(item.a[0],item.a[1]);ctx.lineTo(item.b[0],item.b[1]);ctx.stroke();break;case'points':ctx.fillStyle=item.color;for(const p of item.vertices){if(p[2]<-1||p[2]>1)continue;ctx.fillRect(p[0],p[1],1,1);}break;case'texture':{const q=item.corners,img=item.image;this.drawTriangle(ctx,img,[0,0,img.width,0,0,img.height],[...q[0].slice(0,2),...q[1].slice(0,2),...q[3].slice(0,2)]);this.drawTriangle(ctx,img,[img.width,0,img.width,img.height,0,img.height],[...q[1].slice(0,2),...q[2].slice(0,2),...q[3].slice(0,2)]);break;}}}ctx.globalAlpha=1;this.info.render={calls,triangles};}
  drawTriangle(ctx,img,s,d){const [u0,v0,u1,v1,u2,v2]=s,[x0,y0,x1,y1,x2,y2]=d,den=u0*(v1-v2)+u1*(v2-v0)+u2*(v0-v1);if(!den)return;const a=(x0*(v1-v2)+x1*(v2-v0)+x2*(v0-v1))/den,b=(y0*(v1-v2)+y1*(v2-v0)+y2*(v0-v1))/den,c=(x0*(u2-u1)+x1*(u0-u2)+x2*(u1-u0))/den,e=(y0*(u2-u1)+y1*(u0-u2)+y2*(u1-u0))/den,tx=(x0*(u1*v2-u2*v1)+x1*(u2*v0-u0*v2)+x2*(u0*v1-u1*v0))/den,ty=(y0*(u1*v2-u2*v1)+y1*(u2*v0-u0*v2)+y2*(u0*v1-u1*v0))/den;ctx.save();ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x1,y1);ctx.lineTo(x2,y2);ctx.closePath();ctx.clip();ctx.transform(a,b,c,e,tx,ty);ctx.drawImage(img,0,0);ctx.restore();}
}
